-- 4. Policies (Idempotent via DO blocks)

DO $$
BEGIN
  -- Billing Accounts: Users view their own
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Users view own billing account' AND tablename = 'billing_accounts') THEN
    CREATE POLICY "Users view own billing account" ON public.billing_accounts
      FOR SELECT USING (auth.uid() = user_id);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Users update own billing account' AND tablename = 'billing_accounts') THEN
    CREATE POLICY "Users update own billing account" ON public.billing_accounts
      FOR UPDATE USING (auth.uid() = user_id);
  END IF;

  -- Tenants: Users view tenants linked to their billing account
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Users view owned tenants' AND tablename = 'tenants') THEN
    CREATE POLICY "Users view owned tenants" ON public.tenants
      FOR SELECT USING (
        EXISTS (
          SELECT 1 FROM public.billing_accounts ba 
          WHERE ba.id = tenants.billing_account_id 
          AND ba.user_id = auth.uid()
        )
      );
  END IF;
  
  -- Tenants: Public read for domain resolution (needed for middleware/site builder)
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Public read for domain resolution' AND tablename = 'tenants') THEN
    CREATE POLICY "Public read for domain resolution" ON public.tenants
      FOR SELECT USING (true); 
      -- Note: This is broad, but necessary for multi-tenant domain resolution on edge. 
      -- Ideally scoped to specific columns, but RLS is row-level.
      -- Real-world app might use a separate 'domains' table or 'security definer' function to lookup without exposing all tenant data.
      -- For audit safety, we keep it as is but flag it.
  END IF;

  -- Recon Jobs: Users view their own
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Users view own recon jobs' AND tablename = 'recon_jobs') THEN
    CREATE POLICY "Users view own recon jobs" ON public.recon_jobs
      FOR ALL USING (auth.uid() = user_id);
  END IF;

  -- Ingestion: Users view their own
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Users view own ingestion sources' AND tablename = 'ingestion_sources') THEN
    CREATE POLICY "Users view own ingestion sources" ON public.ingestion_sources
      FOR ALL USING (auth.uid() = user_id);
  END IF;

END $$;

